-- 📚 꼭집 주거 사전 — 보증금↔월임대료 전환 이율 · LH · 국민·영구·행복·매입 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 🔵 2026-10-14 「감액 전환 월임대료 끝자리」 갈래(dn_*) — 세대 행 extracted_facts.최대전환 의 감액마다 기록된 월임대료가
--   「기본 월임대료 + 감액금액×3.5%÷12 를 10원 미만 버림」과 같은가(버림) · 반올림에만 같은가(반올림) · 둘 다 아닌가.
--   🔴 이 갈래만 범위가 다르다 — 공고일·공급기관·유형 거름 없이 최대전환 값이 있는 세대 행 전부(dn_rows = 감액 원소 수).
--   둘 다 아님 중 …19841 은 ⚠️ 행 「임대조건 최대전환 값 표기 주의」로 이미 알린 공고다.
-- 🔵 2026-11-09(우편함 「코드·운영 — 모드 정의 하나 … · 📚 재계산 파일 #34·#19」 4장) — 30초를 넘어(2026-11-09 조사 · 종전 15~17초) 가볍게 고침:
--   cap60·m24 가 「y join s」를 s 86행마다 y 전체(2026 정책 11,166행)에 정규식으로 다시 훑었다(실측 16.7초 중 14.9초). y 를 「보증금 전환」 ∧ s 공고 행만으로
--   먼저 거른다(yc → s → y · 모든 y 사용처가 그 두 조건을 이미 건다 — 결과 같음: 옛 SQL 을 enable_nestloop=off 로 돌린 값과 JSON 이 같았다).
-- 확인 2026-11-09 · 실행 약 2.5초(관리 API 왕복) · 결과:
-- {"anns": 86, "with_rate": 69, "up6": 57, "dn35": 47, "other": null, "cap60": 42, "m24": 32, "ex": ["20652_1_서울특별시_영등포구", "2015122300020965", "2015122300020944", "2015122300020933"], "dn_rows": 713, "dn_anns": 68, "dn_end": {"버림": 699, "둘 다 아님": 13, "반올림": 1}, "dn_round_ex": ["2015122300020710"], "dn_neither_ex": ["2015122300019841", "2015122300020698", "2015122300020733", "2015122300020752", "2015122300020816", "2015122300020887", "2015122300021025"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),yc as(select p.announcement_id,p.content_raw,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),s as(select distinct announcement_id from yc where cls='보증금 전환' and org='LH' and std in('국민임대','영구임대','행복주택','매입임대')),y as materialized(select yc.announcement_id,regexp_replace(yc.content_raw,'\s+',' ','g')t,yc.cls from yc where yc.cls='보증금 전환' and yc.announcement_id in(select announcement_id from s)),r as(select distinct y.announcement_id,x[1]::numeric v from y join s using(announcement_id) cross join lateral regexp_matches(y.t,'(?:연|이율|요율)\s*[:)]?\s*([0-9]+(?:\.[0-9]+)?)\s*%','g')x where y.cls='보증금 전환'),dn as(select h.announcement_id,(case when (f->'감액'->>'월임대료')::numeric=floor((h.monthly_rent+(f->'감액'->>'금액')::numeric*0.035/12)/10)*10 then '버림' when (f->'감액'->>'월임대료')::numeric=round((h.monthly_rent+(f->'감액'->>'금액')::numeric*0.035/12)/10)*10 then '반올림' else '둘 다 아님' end)c from housing_units h cross join lateral jsonb_array_elements(h.extracted_facts->'최대전환')f where jsonb_typeof(h.extracted_facts->'최대전환')='array' and f ? '감액')select json_build_object('anns',(select count(*) from s),'with_rate',(select count(distinct announcement_id) from r),'up6',(select count(distinct announcement_id) from r where v=6),'dn35',(select count(distinct announcement_id) from r where v=3.5),'other',(select json_object_agg(v,n) from(select v,count(*)n from r where v not in(6,3.5) group by v)q),'cap60',(select count(distinct announcement_id) from y join s using(announcement_id) where cls='보증금 전환' and t~'최대\s*60\s*%'),'m24',(select count(distinct announcement_id) from y join s using(announcement_id) where cls='보증금 전환' and t~'24\s*개월'),'ex',(select json_agg(i) from(select announcement_id i from r where v=6 intersect select announcement_id from r where v=3.5 order by 1 desc limit 4)q),'dn_rows',(select count(*) from dn),'dn_anns',(select count(distinct announcement_id) from dn),'dn_end',(select json_object_agg(c,n) from(select c,count(*)n from dn group by c)q),'dn_round_ex',(select json_agg(distinct announcement_id) from dn where c='반올림'),'dn_neither_ex',(select json_agg(distinct announcement_id) from dn where c='둘 다 아님'))j;
